tmpfile_adapter:
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
/* Keep engine scratch files in the writable workspace on this test host. */
FILE *tmpfile(void) {
    const char *dir=getenv("TMPDIR");
    if (!dir) { errno=ENOENT; return NULL; }
    char *name=NULL;
    if (asprintf(&name,"%s/ngspice-XXXXXX",dir)<0) return NULL;
    int fd=mkstemp(name);
    if(fd<0) { free(name); return NULL; }
    unlink(name); free(name);
    FILE *stream=fdopen(fd,"w+b");
    if(!stream) close(fd);
    return stream;
}
FILE *tmpfile64(void) { return tmpfile(); }
